package com.wandertrace.controller;
import com.wandertrace.dto.*;import com.wandertrace.dto.TripDtos.*;import com.wandertrace.security.CurrentUser;import com.wandertrace.service.TripService;import jakarta.servlet.http.HttpSession;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/trips") public class TripController {private final TripService trips;private final CurrentUser current;public TripController(TripService trips,CurrentUser current){this.trips=trips;this.current=current;}private UUID user(HttpSession s){return current.require(s);}@GetMapping public ApiResponse<List<Trip>> list(HttpSession s){return ApiResponse.ok(trips.list(user(s)));}@GetMapping("/{id}")public ApiResponse<Trip> get(@PathVariable UUID id,HttpSession s){return ApiResponse.ok(trips.get(user(s),id));}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ApiResponse<Trip> create(@Valid @RequestBody CreateTrip r,HttpSession s){return ApiResponse.ok(trips.create(user(s),r));}@PutMapping("/{id}")public ApiResponse<Trip> update(@PathVariable UUID id,@Valid @RequestBody UpdateTrip r,HttpSession s){return ApiResponse.ok(trips.update(user(s),id,r));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable UUID id,HttpSession s){trips.delete(user(s),id);}@GetMapping("/{id}/members")public ApiResponse<List<Member>> members(@PathVariable UUID id,HttpSession s){return ApiResponse.ok(trips.members(user(s),id));}@PostMapping("/{id}/members")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<Member> add(@PathVariable UUID id,@Valid @RequestBody AddMember r,HttpSession s){return ApiResponse.ok(trips.addMember(user(s),id,r));}@PatchMapping("/{tripId}/members/{userId}")public ApiResponse<Void> change(@PathVariable UUID tripId,@PathVariable UUID userId,@Valid @RequestBody UpdateMember r,HttpSession s){trips.changeMember(user(s),tripId,userId,r);return ApiResponse.ok(null);}@DeleteMapping("/{tripId}/members/{userId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void remove(@PathVariable UUID tripId,@PathVariable UUID userId,HttpSession s){trips.removeMember(user(s),tripId,userId);}}
